def match_parens(lst):
    # Verify input list contains two strings
    if len(lst) != 2 or not all(isinstance(s, str) for s in lst):
        return 'No'

    # Verify both strings consist of only open or close parentheses
    if not all(c in '()' for s in lst for c in s):
        return 'No'

    # Concatenate the two strings
    concatenated = lst[0] + lst[1]

    # Check if resulting string is balanced
    stack = []
    for char in concatenated:
        if char == '(':
            stack.append(char)
        elif char == ')':
            if not stack:
                return 'No'
            stack.pop()

    # Return 'Yes' if balanced, 'No' if not balanced
    return 'Yes' if not stack else 'No'

